\label{lem:mv-jvp}
  Let ${F:\Lambda(V)\to\Lambda(V)}$ be a differentiable function. Let~${\{b_J\}_J}$ be basis blades, with reciprocal blades~${\{b^J\}_J}$, and~${\mathcal{I}\subset 2^{[n]}}$.
  If~${X=\sum_{J\in\mathcal I}X_J b_J}$ ranges over the linear subspace of~${\Lambda(V)}$ defined by~${\mathcal{I}}$, then
 \begin{equation*}
   \partial_{\mathcal I}F(X)
   =
   \operatorname{\medmath\sum}_{J\in\mathcal I}
   b^J\,\text{\tt{jvp}}(F,X,b_J)\;.
 \end{equation*}
 Similarly, if~${\mathcal{O}}$ indexes a set of basis blades in the codomain of~${F}$, then
 \begin{equation*}
      \partial_{\mathcal O}F(X)
      =
      \operatorname{\medmath\sum}_{K\in\mathcal O}
      \text{\tt vjp}_{\langle \cdot, \cdot \rangle}(F,X,b^K)\, b_K
      \;.
 \end{equation*}

\label{prop:basis_indep}
Let $\mathcal I\subset 2^{[n]}$ and take $W:=\operatorname{span}\{b_J\}_{J\in\mathcal I}=\operatorname{span}\{b^J\}_{J\in\mathcal I}$. The operator
$\partial_{\mathcal I}F=\sum_{J\in\mathcal I} b^J\,\partial F/\partial X_J$ depends only on the subspace $W$ and the pairing, not on the basis $\{b_J\}_{J\in\mathcal I}$ chosen for $W$.

Suppose that we had a different basis $\{c_J\}_{J\in \mathcal I}$ of $W$. By virtue of $\{b_J\}$ being a basis for $W$, every $c_J$ must be expressible as $c_J = \sum_{K} \mathbf{A}_{JK} b_K$ for some matrix $\mathbf{A}$. The reciprocals $\{b^J\}$ also form a basis, and thus should satisfy $c^J = \sum_{K} \mathbf{D}_{JK} b^K$ for some matrix $\mathbf{D}$. We can then note:
\begin{align}
    \delta_{JL} &= \langle c^J, c_L \rangle = \sum_{K,M} \mathbf{D}_{JK}\mathbf{A}_{LM} \langle b^k, b_M\rangle \\
    &= \sum_K \mathbf{D}_{JK} \mathbf{A}_{LK} = (\mathbf{DA}^\top)_{JL}
\end{align}
Therefore, $\mathbf{D} = (\mathbf{A}^\top)^{-1}$.

Next, note that for an arbitrary multivector $X\in W$, we have:
\begin{align}
    X &= \sum_J X'_J c_J \\
    &= \sum_J X'_J \left( \sum_K A_{JK} b_K \right) \\
    &= \sum_K \left(\sum_J A_{JK} X'_J \right) b_K \\
    &= \sum_K X_K b_K
\end{align}
This relates the coordinates $X_K$ and $X'_J$, and immediately implies:
\begin{align}
\frac{\partial X_K}{\partial X'_J} = A_{JK}
\end{align}
With this established, we can easily simplify the following multivector derivative expressed in the $\{c_J\}$ basis as one expressed in the $\{b_J\}$ basis:
\begin{align}
    \partial F &= \sum_J c^J \frac{\partial F}{\partial X'_J} \\
    &= \sum_J \left[\sum_{K} b^K (A^\top)^{-1}_{JK} \right] \left[ \sum_L \frac{\partial F}{\partial X_L} \frac{\partial X_L}{\partial X'_J}\right] \\
    &= \sum_{K,L} b^K \left[\sum_J (A^\top)^{-1}_{JK} A_{JL} \right] \frac{\partial F}{\partial X_L} \\
    &= \sum_{K,L} b^K \delta_{KL} \frac{\partial F}{\partial X_L} \\
    &= \sum_K b^K \frac{\partial F}{\partial X_K}
\end{align}

Take $X = \sum_{J\in\mathcal I} X_J b_J \in W$. Then by definition,
\begin{equation}
\frac{\partial F}{\partial X_J} = \frac{d}{dt} F(X + t b_J) \big|_{t=0} = dF_X[b_J] = \texttt{jvp}(F, X, b_J)
\end{equation}
so $\partial_\mathcal{I} F(X) = \sum_{J\in\mathcal{I}} b^J \texttt{jvp}(F, X, b_J)$.
